from typing import Final

def exact_face_count(k: int, steps: int) -> int:
    """Count all faces, including the empty face."""
    if k < 0 or steps < 0:
        raise ValueError("parameters must be nonnegative")
    return (1 << k) * (steps + 2)

for k in range(5):
    print(k, [exact_face_count(k, s) for s in range(6)])

from itertools import combinations
from typing import Hashable, Sequence, TypeVar

V = TypeVar("V", bound=Hashable)

def cone_faces(apex: V, base: Sequence[V]) -> set[frozenset[V]]:
    if apex in base:
        raise ValueError("apex must be fresh")
    return {
        frozenset((apex, *chosen))
        for r in range(len(base) + 1)
        for chosen in combinations(base, r)
    }

faces = cone_faces("v", ["a", "b", "c"])
print(*sorted(map(sorted, faces), key=lambda x: (len(x), x)), sep="\n")
assert len(faces) == 8

from math import comb

def face_vector(k: int, steps: int) -> list[int]:
    """Return counts indexed by face cardinality."""
    if k < 0 or steps < 0:
        raise ValueError("parameters must be nonnegative")
    return [
        comb(k + 1, j) + (steps * comb(k, j - 1) if j else 0)
        for j in range(k + 2)
    ]

for k, steps in [(1, 6), (2, 5), (3, 4)]:
    vector = face_vector(k, steps)
    print(f"k={k}, steps={steps}: {vector}, total={sum(vector)}")

